-- Seed N4 đầy đủ — Minna no Nihongo quyển 2 (Bài 26-50).
-- Nguồn chính: jes.edu.vn (tu-vung-minna-no-nihongo-bai-N / ngu-phap-minna-no-nihongo-bai-N),
--   cào trực tiếp bảng từ vựng + nội dung ngữ pháp thật, sau đó tóm tắt/viết lại ngữ pháp
--   theo văn phong seed_content_n5_full.sql (không copy nguyên văn dài dòng từ nguồn).
-- Khoảng trống nguồn (4 trang không tồn tại trên jes.edu.vn — đã kiểm tra 404 + tìm slug thay
--   thế + site search, không tìm được):
--   - Từ vựng Bài 27, 31, 32: danh sách rút gọn (~20 từ/bài) từ kiến thức chuẩn giáo trình.
--   - Ngữ pháp Bài 48: 5 điểm về thể sai khiến (させます) từ kiến thức chuẩn giáo trình.
-- Kanji (208 chữ): KHÔNG có trên jes.edu.vn theo bài (nguồn chỉ có từ vựng+ngữ pháp) — lấy
--   kiến thức chuẩn Kanji Renshuuchou II, đối chiếu chéo với kanji thực xuất hiện trong từ vựng
--   N4 cào được để chọn danh sách + gắn bài xuất hiện đầu tiên (khác cách N5 làm — N5 có
--   13/91 kanji chưa gắn bài nào vì không có nguồn đối chiếu).
-- Giới hạn đã biết (giống N5): vocabulary không có part_of_speech/example_jp/example_vi
--   (nguồn không cung cấp). Kanji không có mnemonic/stroke_data (SVG).
-- Idempotent: UUID cố định (uuid5 theo nội dung), on conflict do nothing — chạy lại an toàn.
--
-- Chạy: supabase db query --linked -f supabase/seed_content_n4_full.sql

