-- Seed N4 — Ngữ pháp (Minna no Nihongo quyển 2, Bài 26-50)
-- Bài 48: nguồn jes.edu.vn thiếu (404) -- viết từ kiến thức chuẩn giáo trình.
-- Các bài khác: giải thích tự viết súc tích dựa trên nội dung thật cào từ jes.edu.vn.
insert into grammar_points (id, title, explanation, example_jp, example_vi, level_id)
select v.id, v.title, v.explanation, v.example_jp, v.example_vi,
       (select id from jlpt_levels where code = 'N4')
from (values
  ('91900726-0a09-58b2-93ba-820d7b479174'::uuid, 'Thể thông thường + んです', 'んです gắn sau thể thông thường của động từ, tính từ, danh từ để giải thích, xác nhận nguyên nhân hoặc bối cảnh của một sự việc mà người nói và người nghe đều đã biết hoặc nhìn thấy.', 'けさ頭が痛いんです。', 'Sáng nay tôi bị đau đầu (nên mới thế này).'),
  ('b0a4841d-49e3-59e9-bce6-caaf958587b5'::uuid, '~んですか', 'Dùng khi người nói nhìn thấy hoặc nghe thấy điều gì đó khác thường rồi hỏi lại để xác nhận nguyên nhân, lý do hoặc muốn biết thêm thông tin chi tiết.', '顔色が悪いですね。どうしたんですか。', 'Sắc mặt anh không tốt nhỉ. Anh bị làm sao vậy?'),
  ('2ed48bed-5f1b-57dc-a72f-afe69d09ae84'::uuid, '~んです (giải thích lý do)', 'Dùng để trả lời, trình bày nguyên nhân lý do khi được hỏi bằng ~んですか, hoặc chủ động bổ sung lý do cho điều vừa nói. Không dùng んです để nêu một sự thật đơn thuần không liên quan đến giải thích.', 'どうして遅れたんですか。バスが来なかったんです。', 'Sao anh đến muộn vậy? Vì xe buýt không đến ạ.'),
  ('962a986f-a4dd-5bfa-8ea5-334bc2ab5a86'::uuid, '~んですが、~', 'Dùng để mở đầu câu chuyện, nêu bối cảnh trước khi đưa ra lời đề nghị, xin phép hoặc mời gọi, mang sắc thái ngập ngừng, lịch sự. Nếu nội dung phía sau đã quá rõ ràng thì có thể lược bỏ.', '日本語で手紙を書いたんですが、ちょっと見ていただけませんか。', 'Tôi vừa viết một lá thư bằng tiếng Nhật, anh có thể xem giúp tôi một chút được không?'),
  ('1682c5a5-7663-58db-9eeb-f1b452e09a42'::uuid, 'Vて + いただけませんか', 'Mẫu câu nhờ vả với mức độ lịch sự cao hơn ~てください, thường dùng khi nhờ người có địa vị cao hơn hoặc người không thân quen.', 'すみませんが、地図を書いていただけませんか。', 'Xin lỗi, anh có thể vẽ giúp tôi bản đồ được không?'),
  ('99a262c4-fe93-561d-87f7-301b5e9beefd'::uuid, 'Từ nghi vấn + Vたら + いいですか', 'Dùng để hỏi xin lời khuyên hoặc chỉ dẫn về việc nên làm gì, nên đi đâu, nên làm như thế nào trong một tình huống cụ thể.', '電話番号がわからないんですが、どうやって調べたらいいですか。', 'Tôi không biết số điện thoại, phải tra thế nào thì tốt ạ?'),
  ('daa1b484-fe1a-5ed6-afbb-302d647b4078'::uuid, 'Động từ khả năng (thể られる/える)', 'Nhóm 1 chuyển âm cuối hàng い sang hàng え rồi thêm ます; nhóm 2 bỏ ます thêm られます; nhóm 3: きます→こられます, します→できます. Thể khả năng biểu thị năng lực làm được việc gì.', 'ミラーさんは漢字が読めます。', 'Anh Miller đọc được chữ Hán.'),
  ('b3cb3ebc-086d-5336-86d6-a444c30724a5'::uuid, 'Nが + Động từ khả năng', 'Diễn tả năng lực hoặc khả năng thực hiện một việc gì đó; đối tượng vốn đi với trợ từ を được đổi thành が, các trợ từ khác giữ nguyên.', 'この銀行でドルが替えられます。', 'Ngân hàng này có thể đổi được đô la.'),
  ('fb8f6d11-b1fd-505b-a3d4-dba0ba98b7f9'::uuid, 'みえます / きこえます', 'みえます (nhìn thấy) và きこえます (nghe thấy) diễn tả một vật hay âm thanh tự nhiên lọt vào tầm mắt, tai mà không cần chủ ý, luôn đi với trợ từ が; khác với みられる/きける là phải chủ động dùng thời gian, năng lực để xem, nghe.', '私の部屋の窓から富士山が見えます。', 'Từ cửa sổ phòng tôi có thể nhìn thấy núi Phú Sĩ.'),
  ('da9be1ff-acb8-5c02-9934-da164713750f'::uuid, 'できます (hoàn thành, xây xong)', 'Diễn tả một sự vật đã được hoàn thành hoặc xây dựng xong, đi với trợ từ が; địa điểm hoàn thành được biểu thị bằng に.', '駅の近くに新しいスーパーができました。', 'Gần ga có một siêu thị mới được xây xong.'),
  ('dd3b2439-3ab7-5944-a4f3-a7bdda1bb1df'::uuid, '~は~ (so sánh, nhấn mạnh chủ đề)', 'Khi danh từ đi sau を hoặc が trở thành chủ đề của câu, trợ từ は sẽ thay thế を/が; với các trợ từ khác thì は được thêm vào sau (では、には、へは...). は còn dùng để so sánh hai vế nối nhau bằng が.', 'ワインは飲みますが、ビールは飲みません。', 'Rượu vang thì tôi uống, còn bia thì không.'),
  ('437e1a49-29af-580a-becd-0fd69b4414e0'::uuid, '~も~ (cũng)', 'も thay thế cho trợ từ を và が, được thêm vào sau các trợ từ khác (riêng へ có thể lược bỏ khi đứng trước も).', '去年アメリカへ行きました。メキシコも行きました。', 'Năm ngoái tôi đã đi Mỹ. Tôi cũng đã đi Mexico.'),
  ('6da97135-c013-5546-9c59-16df67480a94'::uuid, '~しか + phủ định (chỉ)', 'しか đứng sau danh từ, số lượng để thay thế trợ từ が/を, luôn đi kèm động từ ở thể phủ định, mang nghĩa chỉ; khác với だけ là đi với thể khẳng định.', '今日、私は15分しか休みませんでした。', 'Hôm nay tôi chỉ nghỉ được có 15 phút thôi.'),
  ('34364521-91dd-59cd-a868-77c34cee80f7'::uuid, 'V1ながらV2', 'Biểu thị chủ thể thực hiện đồng thời hai hành động trong cùng một khoảng thời gian, động từ chính đặt ở V2.', '音楽を聞きながら食事します。', 'Tôi vừa ăn cơm vừa nghe nhạc.'),
  ('79105b52-ec1b-52fa-935e-36ea3be86cee'::uuid, 'Vて + います (thói quen)', 'Diễn tả một thói quen hay hành vi được lặp lại đều đặn; nếu là thói quen trong quá khứ thì dùng ~ていました.', '毎朝ジョギングをしています。', 'Mỗi sáng tôi đều chạy bộ.'),
  ('c75cd551-ca8e-512b-a8e3-73eaf172ee4f'::uuid, 'Thể thông thường + し、~', 'Dùng し để liệt kê nhiều lý do hoặc đặc điểm cùng chiều (ưu điểm hoặc nhược điểm) của một chủ thể, ngụ ý ngoài các lý do nêu ra còn có thể có lý do khác nữa; khác với から chỉ nêu một nguyên nhân duy nhất.', 'ワット先生は熱心だし、まじめだし、経験もあります。', 'Thầy Watt vừa nhiệt tình, vừa nghiêm túc, lại có kinh nghiệm nữa.'),
  ('efd82dde-ee80-57bb-ad18-ec806abd8026'::uuid, 'Vて + います (trạng thái do hành động gây ra)', 'Dùng với nội động từ để diễn tả trạng thái hiện tại là kết quả của một động tác, hành động đã xảy ra trước đó.', '電気がついています。', 'Đèn đang bật (sáng).'),
  ('fca1e355-ba2d-53b8-9f30-b46714da645b'::uuid, 'Nが + Vて + います (miêu tả trạng thái)', 'Miêu tả nguyên vẹn trạng thái đang bày ra trước mắt người nói, chủ thể của trạng thái được đánh dấu bằng trợ từ が; nếu là trạng thái trong quá khứ thì dùng ~ていました.', '窓が閉まっています。', 'Cửa sổ đang đóng.'),
  ('0251e7b9-150f-5948-bdc1-d08c7fc3e248'::uuid, 'Nは + Vて + います (chủ đề hoá)', 'Khi muốn đưa sự vật, sự việc đã biết làm chủ đề của câu thì thay trợ từ が bằng は, thường dùng kèm các từ chỉ định この/その/あの.', 'そのいすは壊れています。', 'Cái ghế đó thì bị hỏng rồi.'),
  ('3da15ef5-17a9-5c57-9b7d-dc6f9275d989'::uuid, 'Vて + しまいます (sẽ hoàn thành xong)', 'Nhấn mạnh một hành động sẽ được hoàn thành, kết thúc trọn vẹn trong tương lai, thường đi kèm もう hoặc ぜんぶ.', '明日までにレポートを書いてしまいます。', 'Tôi sẽ viết xong báo cáo trước ngày mai.'),
  ('3f01068b-f881-5ffe-8138-0bab086485df'::uuid, 'Vて + しまいました (tiếc nuối)', 'Diễn tả một việc đáng tiếc, ngoài ý muốn đã xảy ra rồi, thể hiện sự hối tiếc hay áy náy của người nói.', 'パスポートをなくしてしまいました。', 'Tôi làm mất hộ chiếu mất rồi.'),
  ('d4d44152-6b4d-587a-8070-d89129cf6460'::uuid, '~ありました (tìm thấy rồi)', 'Dùng khi người nói tìm thấy được vật gì đó đang bị thất lạc.', 'あ、財布がありました。', 'A, tìm thấy cái ví rồi.'),
  ('6316114b-feb5-5d92-b637-c2368cb74a2f'::uuid, 'どこかで / どこかに', 'Với どこかへ và なにかを thì có thể lược bỏ trợ từ へ/を, nhưng で trong どこかで và に trong どこかに thì không thể lược bỏ.', 'どこかで財布をなくしてしまいました。', 'Tôi đánh rơi ví ở đâu đó rồi.'),
  ('e5854aea-8b85-5c29-ab33-8b147335bdfd'::uuid, 'Vて + あります', 'Diễn tả một trạng thái đang tồn tại là kết quả của một hành động có chủ ý của ai đó; động từ dùng là ngoại động từ.', '壁に絵がかけてあります。', 'Trên tường có treo một bức tranh.'),
  ('133a89ad-0458-503f-b145-331efcbf4ee4'::uuid, 'N1に N2が Vて + あります', 'Diễn tả chi tiết một vật đang hiện hữu ở trạng thái nào đó tại một địa điểm, do có ai đã chủ ý làm; động từ dùng là ngoại động từ.', 'カレンダーに今週の予定が書いてあります。', 'Trên lịch có ghi lịch làm việc của tuần này.'),
  ('cecfc982-d135-5f16-b76a-9bf2a83704f4'::uuid, 'N2は N1に Vて + あります', 'Đưa N2 (vật) lên làm chủ đề câu; thường dùng với もう để diễn tả một việc đã được chuẩn bị sẵn. Phân biệt: ~ています đi với nội động từ (miêu tả tình trạng hiện tại), còn ~てあります đi với ngoại động từ (kết quả có chủ ý).', '誕生日のプレゼントはもう買ってあります。', 'Quà sinh nhật thì tôi đã mua sẵn rồi.'),
  ('01e5b11e-5d8a-5f50-add2-941a977b0bf4'::uuid, 'Vて + おきます', 'Diễn tả việc chuẩn bị, hoàn thành trước một việc gì đó để sẵn sàng cho sau này, hoặc giữ nguyên một trạng thái nào đó.', '旅行の前にホテルを予約しておきます。', 'Trước khi đi du lịch, tôi đặt phòng khách sạn trước.'),
  ('0a0b88f4-f9e1-5077-a391-a9d973009a8b'::uuid, 'まだ + Động từ (thể khẳng định)', 'Diễn tả một trạng thái hay hành động vẫn còn đang tiếp diễn.', '雨はまだ降っていますよ。', 'Trời vẫn còn đang mưa đấy.'),
  ('f527080b-af2b-57a4-a0ad-13c6b60befc2'::uuid, 'それ (chỉ điều vừa nghe)', 'それ dùng để chỉ nội dung mà đối phương vừa mới nói ngay trước đó trong cuộc hội thoại.', 'ブロードウェイでミュージカルを見たいんです。それはいいですね。', 'Tôi muốn xem nhạc kịch ở Broadway. Hay đấy nhỉ.'),
  ('209e82db-8ba1-58ca-81ec-9ca6bf6321e5'::uuid, 'Thể ý định (意向形)', 'Nhóm 1: đổi âm cuối thể ます sang hàng お rồi thêm う; nhóm 2: thêm よう vào thân động từ; nhóm 3: する→しよう, くる→こよう.', '少し休もう。', 'Nghỉ một chút thôi.'),
  ('7b6ed5b5-ea6a-5105-a0cb-d9e1cd47ea5b'::uuid, 'Vý định + と + おもっています', 'Biểu thị ý định đã được hình thành từ trước và vẫn đang duy trì đến hiện tại của người nói (cũng dùng được cho ngôi thứ ba).', '週末は海へ行こうと思っています。', 'Tôi đang định đi biển vào cuối tuần.'),
  ('88812a45-0959-58f5-8454-542f5789826c'::uuid, 'V辞書形/Vない + つもりです', 'つもりです diễn tả một quyết định, dự định chắc chắn và dứt khoát hơn ~とおもっています; thể từ điển dùng cho ý định làm, thể ない dùng cho ý định không làm.', '明日からたばこを吸わないつもりです。', 'Tôi quyết định từ ngày mai sẽ không hút thuốc nữa.'),
  ('d4d342af-d9ef-5fff-9857-449504828bd4'::uuid, 'N/V辞書形 + よてい (dự định)', 'Dùng để nói về một kế hoạch, dự định đã được sắp xếp trước, khách quan hơn つもり.', '旅行は一週間の予定です。', 'Theo dự định, chuyến du lịch sẽ kéo dài một tuần.'),
  ('245b3509-b409-53fa-98cd-eb2290cbad65'::uuid, 'まだ + Vて + いません', 'Diễn tả một việc gì đó vẫn chưa được thực hiện, chưa xảy ra tính đến thời điểm nói.', 'レポートはまだ書いていません。', 'Tôi vẫn chưa viết xong báo cáo.'),
  ('4a3eaf12-e64e-5383-8720-1be154463261'::uuid, 'Vた/Vない + ほうがいいです', 'Dùng để khuyên ai đó nên hoặc không nên làm gì thì tốt cho họ; khác với ~たらいい (đưa ra lựa chọn, so sánh), đây chỉ là lời khuyên đơn giản.', '毎日運動したほうがいいです。', 'Hằng ngày nên tập thể dục thì tốt hơn.'),
  ('2e978ead-c1a4-502b-b3f7-2b388666aa5a'::uuid, 'Thể thông thường + でしょう', 'Biểu thị sự suy đoán của người nói dựa trên một căn cứ, thông tin nào đó; danh từ và tính từ đuôi な ở thể thông thường phải bỏ だ.', '明日は雨が降るでしょう。', 'Ngày mai có lẽ trời sẽ mưa.'),
  ('c9b3c3d1-eb33-5ec1-b16d-6e6e8848d3aa'::uuid, 'Thể thông thường + かもしれません', 'Biểu thị sự phỏng đoán của người nói nhưng với mức độ chắc chắn thấp hơn でしょう, dưới 50%.', '午後から雪が降るかもしれません。', 'Có thể chiều nay tuyết sẽ rơi cũng nên.'),
  ('0ecb20f0-14ee-59d5-bd6b-3a21683881b3'::uuid, 'きっと / たぶん / もしかしたら', 'きっと biểu thị mức độ chắc chắn cao (thường đi với でしょう); たぶん biểu thị mức độ chắc chắn thấp hơn một chút; もしかしたら đi kèm ~かもしれません biểu thị khả năng thấp nhất trong ba từ.', 'もしかしたら3月に卒業できないかもしれません。', 'Biết đâu tháng 3 tôi không tốt nghiệp được cũng nên.'),
  ('259db7b3-8dac-5927-8fcb-aa6c7317b2a4'::uuid, 'Lượng từ + で (giới hạn)', 'で đứng sau lượng từ chỉ tiền bạc, thời gian, số lượng để biểu thị mức giới hạn cần thiết để một việc được thực hiện.', '3万円でこのカメラが買えますか。', '3 vạn yên có mua được cái máy ảnh này không?'),
  ('bc6aef63-a54f-58a2-82b4-e4b1b6c7934f'::uuid, 'Thể mệnh lệnh / thể cấm chỉ', 'Thể mệnh lệnh: nhóm 1 đổi âm cuối thể ます sang hàng え; nhóm 2 thêm ろ; nhóm 3: くる→こい, する→しろ. Thể cấm chỉ: thêm な vào sau thể từ điển của cả ba nhóm.', 'ここに入るな。', 'Không được vào đây.'),
  ('252a042d-7663-5dd0-b851-2385f9f709a2'::uuid, 'Cách dùng thể mệnh lệnh/cấm chỉ', 'Mang sắc thái mạnh, cứng rắn nên chỉ dùng khi người trên nói với người dưới, giữa bạn bè nam giới thân thiết, khi cổ vũ, trong tình huống khẩn cấp hoặc biển báo, hiệu lệnh.', '頑張れ。', 'Cố lên.'),
  ('bdabc79b-f9cd-5fe6-b98a-e82ae40927bf'::uuid, '~と読みますか / ~と書きますか', 'Dùng để hỏi cách đọc hoặc cách viết của một từ, chữ viết nào đó.', 'あの漢字は何と読むんですか。', 'Chữ Hán kia đọc là gì vậy?'),
  ('d891bbd5-3301-5b17-8ddd-ac8c849daf69'::uuid, 'N1は N2という意味です', 'Dùng để hỏi và trả lời về ý nghĩa của một từ, ký hiệu.', 'このマークはどういう意味ですか。洗濯できるという意味です。', 'Ký hiệu này có nghĩa là gì? Có nghĩa là có thể giặt được.'),
  ('bf5d192b-fa3f-5132-a727-8ea7dcac3669'::uuid, 'Thể thông thường + と言っていました', 'Dùng để truyền đạt lại lời nói, lời nhắn của người thứ ba, khác với dùng いいました để trích dẫn nguyên văn lời nói.', '田中さんは明日休むと言っていました。', 'Anh Tanaka nói là ngày mai anh ấy sẽ nghỉ.'),
  ('d441420b-f0c0-5ef9-846d-219a7eae2213'::uuid, 'Thể thông thường + と伝えていただけませんか', 'Dùng khi muốn nhờ ai đó truyền đạt lại lời nhắn cho người khác một cách lịch sự.', '渡辺さんに、明日のパーティーは6時からだと伝えていただけませんか。', 'Anh có thể nhắn với chị Watanabe rằng bữa tiệc ngày mai bắt đầu từ 6 giờ được không?'),
  ('c242364a-ea52-5150-8d18-659791d681bf'::uuid, 'N の/V + とおりに', 'Diễn tả một hành động được thực hiện đúng theo nội dung, cách thức đã được chỉ ra ở danh từ hoặc động từ đứng trước; hành động đã biết dùng thể た, hành động sắp làm dùng thể từ điển.', '説明書のとおりに、組み立てました。', 'Tôi đã lắp ráp đúng theo hướng dẫn.'),
  ('53f8145c-c986-5b96-b71f-118bcb479e1f'::uuid, 'N の/Vた + あとで', 'Diễn tả hành động ở vế sau xảy ra sau khi hành động, sự việc ở vế trước đã hoàn thành; nhấn mạnh trình tự thời gian rõ hơn so với ~てから.', '仕事のあとで、飲みに行きませんか。', 'Sau khi xong việc, anh đi uống cùng tôi không?'),
  ('008acea1-975e-5036-b9fe-ade248c34720'::uuid, 'Vて / Vないで + V2', 'Diễn tả trạng thái hoặc cách thức đi kèm khi thực hiện hành động ở V2.', 'しょうゆをつけて食べます。', 'Chúng tôi ăn có chấm xì dầu.'),
  ('ea58fc27-64c0-5897-af8a-ddf44249f49f'::uuid, 'Vないで、V2 (lựa chọn không làm)', 'Dùng khi hai việc không thể làm đồng thời, người nói chọn thực hiện V2 mà không làm V1.', '日曜日はどこも行かないで、うちでゆっくり休みます。', 'Chủ nhật tôi không đi đâu cả mà chỉ ở nhà nghỉ ngơi.'),
  ('bf84a3a2-4384-5bfa-9c8a-c6a1901e7f52'::uuid, 'Cách tạo thể điều kiện ば', 'Nhóm 1: đổi âm cuối い→え rồi thêm ば; nhóm 2: bỏ ます thêm れば; nhóm 3: くれば/すれば. Tính từ い: đổi い thành ければ; tính từ な và danh từ: thêm なら.', '安ければ、買います。', 'Nếu rẻ thì tôi sẽ mua.'),
  ('4a2eb72d-ee35-5d60-ad32-40d73c8db400'::uuid, 'Cách dùng thể điều kiện ば', 'Diễn tả điều kiện cần thiết để một việc xảy ra, hoặc quyết định của người nói trong một tình huống giả định.', 'ボタンを押せば、ドアが開きます。', 'Nếu ấn nút thì cửa sẽ mở.'),
  ('b2f93767-b00a-5bdf-941d-4128f2d4da13'::uuid, 'Hạn chế của thể điều kiện ば', 'Nếu vế sau biểu thị chủ ý, mệnh lệnh, hoặc hai vế khác chủ ngữ mà vế sau mang tính chủ ý thì không dùng được ば.', '時間があれば、テレビを見ます。', 'Nếu có thời gian thì tôi sẽ xem ti vi.'),
  ('08846468-b57f-5ed4-8835-358132d90f6f'::uuid, 'Phân biệt ば / と / たら', 'と diễn tả kết quả tất yếu, vế sau không mang tính chủ ý; たら có thể dùng cả khi hai vế cùng chủ ngữ và vế sau mang tính chủ ý, linh hoạt hơn ば.', 'ハイフォンへ来たら、ぜひ連絡してください。', 'Nếu bạn đến Hải Phòng thì nhất định hãy liên lạc với tôi nhé.'),
  ('0657e35c-2b40-56ec-9362-0c0706174b27'::uuid, 'Từ nghi vấn + Vば + いいですか', 'Dùng để hỏi xin chỉ dẫn hoặc lời khuyên, dùng thể điều kiện ば thay cho たら trong mẫu どうしたらいいですか đã học ở bài 26.', '電話番号がわからないんですが、どうすればいいですか。', 'Tôi không biết số điện thoại, phải làm thế nào thì tốt ạ?'),
  ('38b5e1c9-1707-5c2a-912c-67023edf7026'::uuid, '~ば~ほど (càng...càng...)', 'Diễn tả sự thay đổi tương ứng về mức độ: điều kiện ở vế trước thay đổi bao nhiêu thì nội dung vế sau thay đổi tương ứng bấy nhiêu.', '新しければ、新しいほどいいです。', 'Càng mới thì càng tốt.'),
  ('3ce2910f-704e-5dcc-92a6-7caa279b5ffc'::uuid, 'V(khả năng/vô ý)辞書形/ない + ように', 'Diễn tả mục đích của hành động ở vế sau nhằm đạt được trạng thái ở vế trước; động từ trước ように thường là động từ không mang chủ ý (thể khả năng, できる, わかる, なる...).', '風邪をひかないように、セーターを着ます。', 'Để không bị cảm, tôi mặc áo len.'),
  ('0eda1c8d-4954-57f7-881f-aff2e3302513'::uuid, 'V khả năng + ように なりました', 'Biểu thị sự biến đổi trạng thái từ không thể làm được sang có thể làm được.', '日本語が話せるようになりました。', 'Tôi đã có thể nói được tiếng Nhật rồi.'),
  ('66b0cb48-bc58-5225-b377-54ac6403585e'::uuid, 'V + ように しています / してください', '~ようにしています diễn tả sự cố gắng duy trì một thói quen; ~ようにしてください diễn tả lời yêu cầu người khác cố gắng làm hay không làm gì đó.', '毎日運動するようにしています。', 'Tôi cố gắng ngày nào cũng vận động.'),
  ('047ae476-c9ce-597b-9e6d-9dcf7b96ed08'::uuid, '~とか~とか', 'Dùng để liệt kê ví dụ, mang tính khẩu ngữ tương tự や nhưng thường được đặt cả ở cuối danh sách.', 'テニスとか、水泳とか、いろいろなスポーツをしています。', 'Tôi chơi nhiều môn thể thao như quần vợt, bơi lội,...'),
  ('cd26029b-6b0b-5a88-9165-0265a78c8c4e'::uuid, 'Cách tạo động từ bị động (受身形)', 'Nhóm 1: đổi âm cuối い→あ rồi thêm れます; nhóm 2: bỏ ます thêm られます; nhóm 3: きます→こられます, します→されます.', '先生にほめられました。', 'Tôi đã được thầy giáo khen.'),
  ('acbf80cf-5615-53d7-91b0-a0acadc35ca4'::uuid, 'N1は N2に + V bị động', 'Diễn tả N1 chịu tác động (bị/được) từ N2.', '私は犬にかまれました。', 'Tôi đã bị chó cắn.'),
  ('1f4a346c-9616-579e-b1d2-55ef70035bd6'::uuid, 'N1は N2に N3を + V bị động', 'Dùng khi hành vi tác động lên một bộ phận, đồ vật của N1, thường mang sắc thái phiền toái, khó chịu cho người bị tác động; nếu là việc được giúp đỡ và cảm thấy biết ơn thì phải dùng ~てもらいます thay vì bị động.', '私は誰かに足を踏まれました。', 'Tôi đã bị ai đó giẫm lên chân.'),
  ('e3165370-a61d-5eeb-b857-c3f3040b30f9'::uuid, 'N(vật/việc) + V bị động (không nêu chủ thể)', 'Khi nói về sự việc mà không cần nêu đối tượng thực hiện, ta lấy vật, việc làm chủ đề và dùng động từ bị động.', '日本の車は世界中へ輸出されています。', 'Ô tô Nhật Bản được xuất khẩu khắp thế giới.'),
  ('81bd8192-d3ab-53ce-b879-f6e8586e27e8'::uuid, 'N1は N2によって + V bị động', 'Dùng khi nói về tác phẩm, phát minh do ai đó tạo ra, sáng tác.', '電話はグラハム・ベルによって発明されました。', 'Điện thoại đã được phát minh bởi Graham Bell.'),
  ('f5fcd252-876e-55f9-b312-0c57076c092e'::uuid, 'N(nguyên liệu)から / N(vật liệu)で + 作られます', 'Khi nói về nguyên liệu để sản xuất ra một vật mà đã biến đổi tính chất thì dùng から, còn khi vật liệu vẫn giữ nguyên hình dạng dễ nhận ra thì dùng で.', 'ビールは麦から造られます。', 'Bia được làm từ lúa mạch.'),
  ('48cb531e-c77b-59af-be61-1672045dfe53'::uuid, 'V辞書形のは + Tính từ です', 'Danh từ hóa động từ bằng の rồi đưa ra nhận xét, đánh giá về hành động đó.', '東京の人は歩くのが速いです。', 'Người Tokyo đi bộ nhanh.'),
  ('093620cc-433d-59b1-8fca-1b057f600095'::uuid, 'V辞書形の を 忘れました', 'Diễn tả việc quên thực hiện một hành động nào đó.', '車の窓を閉めるのを忘れました。', 'Tôi quên đóng cửa sổ ô tô.'),
  ('a08c5285-9d76-5f9c-b6d6-d0a40929e607'::uuid, 'V辞書形の を 知っていますか', 'Dùng để hỏi người nghe có biết một sự việc nào đó hay không; chú ý phân biệt しりません (không biết, kể cả sau khi hỏi) và しりませんでした (không biết trước đó, nhưng vừa mới biết).', '鈴木さんが来月結婚するのを知っていますか。', 'Anh có biết là tháng sau anh Suzuki sẽ kết hôn không?'),
  ('2ac8099a-6181-5f02-9a91-87cf3142bebb'::uuid, 'Thể thông thường の は Nです', 'の thay thế cho danh từ chỉ đồ vật, người, địa điểm,... để nêu chủ đề của câu.', '1年で一番忙しいのは12月です。', 'Trong năm, tháng bận rộn nhất là tháng 12.'),
  ('0010e88a-9920-5fe4-942d-3b9d9c859064'::uuid, '~とき も/の/に/や、~', 'とき là một danh từ nên có thể kết hợp với nhiều trợ từ khác nhau (ときに, ときの, ときも, ときや) để diễn tả các sắc thái thời điểm khác nhau.', '疲れたときや、さびしいときは、田舎を思い出します。', 'Những lúc mệt mỏi hay buồn bã, tôi lại nhớ về quê.'),
  ('0a050003-2565-587e-8b6b-e1e89c43e277'::uuid, 'V/Adj/N thể て・で、~ (nguyên nhân)', 'Vế trước chỉ nguyên nhân, vế sau là kết quả (thường liên quan cảm xúc, trạng thái, khả năng); không dùng khi vế sau mang tính chủ ý rõ ràng hoặc khi hai vế có trình tự thời gian trước sau rõ ràng, lúc đó phải dùng から.', 'ニュースを聞いて、びっくりしました。', 'Tôi đã giật mình khi nghe tin đó.'),
  ('1517f783-6665-5472-9c67-5192ebe5c609'::uuid, 'N + で (nguyên nhân do sự kiện tự nhiên)', 'で đứng sau danh từ chỉ hiện tượng tự nhiên hoặc sự cố (じこ, じしん, かじ...) để biểu thị nguyên nhân; không dùng khi vế sau mang tính chủ ý.', '事故で電車が止まりました。', 'Vì tai nạn nên tàu điện đã dừng lại.'),
  ('9705d735-12b2-528a-8204-85f2537727af'::uuid, 'Thể thông thường + ので、~', 'Giống から, ので cũng chỉ nguyên nhân lý do nhưng mang sắc thái khách quan, nhẹ nhàng hơn; không dùng với mệnh lệnh hay cấm đoán ở vế sau; danh từ, tính từ な ở thể thông thường dùng だ.', 'バスがなかなか来なかったので、大学に遅れました。', 'Vì xe buýt mãi không đến nên tôi đã đến trường muộn.'),
  ('383bb304-e3cd-59a0-8de6-01efd6d54324'::uuid, 'N の/V辞書形 + とちゅうで', 'Diễn tả một sự việc xảy ra trên đường đi, giữa chừng một hành động nào đó.', '来るとちゅうで、事故があったので、バスが遅れてしまったんです。', 'Trên đường đến đây có xảy ra tai nạn nên xe buýt đã bị trễ.'),
  ('09681c40-4425-5618-a35e-7ec81780729f'::uuid, 'Từ nghi vấn + Thể thông thường + か、~', 'Dùng để lồng một câu hỏi có từ nghi vấn vào làm thành phần của một câu văn khác.', '会議はいつ終わるか、わかりません。', 'Tôi không biết khi nào thì cuộc họp kết thúc.'),
  ('c1604572-5e83-59da-a75b-54e78495dc9c'::uuid, 'Thể thông thường + かどうか、~', 'Dùng để lồng một câu hỏi không có từ nghi vấn (câu hỏi có/không) vào làm thành phần của câu văn khác.', 'その話はほんとうかどうか、わかりません。', 'Tôi không biết chuyện đó có thật hay không nữa.'),
  ('d71c7ca9-7214-533d-98d8-85328b9b4ab8'::uuid, 'Vて + みます', 'Diễn tả ý thử làm một việc gì đó để xem kết quả ra sao.', 'もう一度考えてみます。', 'Tôi sẽ thử suy nghĩ lại một lần nữa.'),
  ('007f8a0e-0915-53de-85df-09f8d21c2498'::uuid, 'Tính từ đuôい (bỏい) + さ', 'Bỏ đuôい của tính từ rồi thêm さ để danh từ hoá tính từ, biểu thị mức độ của tính chất đó.', 'この橋は長さが1000メートルです。', 'Cây cầu này dài 1000 mét.'),
  ('ad41c647-34a6-5204-88d7-7e04849dda31'::uuid, 'N/V辞書形 + でしょうか', 'Cách hỏi lịch sự, nhẹ nhàng hơn か, có thể dùng cả khi người nói không chắc câu trả lời lẫn khi biết rõ câu trả lời để hỏi cho lịch sự.', 'ハンスさんは学校でどうでしょうか。', 'Không biết Hans ở trường thế nào nhỉ?'),
  ('7cf3fe50-d5b0-5a82-8c52-4e91082ab511'::uuid, 'あげます / いただきます / くださいます', 'あげます: tôi cho người ngang hàng (やります cho người dưới, động thực vật; さしあげます cho người trên); いただきます: khiêm nhường ngữ của もらいます, dùng khi nhận từ người trên; くださいます: dùng khi người trên cho, tặng mình, chủ ngữ luôn là người khác chứ không phải わたし.', '先生は私にボールペンをくださいました。', 'Thầy giáo đã cho tôi một cây bút bi.'),
  ('747d7b23-1c75-5123-a284-95ef64c233c9'::uuid, 'Vて + やります/いただきます/くださいます', 'Cách nói cho-nhận về hành vi: ~てやります (làm gì đó cho người dưới, động vật với thiện chí), ~ていただきます (khiêm nhường, được người trên làm cho gì đó), ~てくださいます (người trên làm gì đó cho mình, biểu thị lòng biết ơn).', '私は鈴木さんに日本語を教えていただきました。', 'Tôi đã được chị Suzuki dạy cho tiếng Nhật.'),
  ('6c81f1cb-60b4-584b-9d8b-31b2211e917a'::uuid, 'Vて + くださいませんか', 'Mẫu câu nhờ vả lịch sự cao dành cho người có địa vị, tuổi tác cao hơn hoặc người không quen biết, mức độ lịch sự cao hơn ~てくれませんか.', 'すみませんが、もう一度説明してくださいませんか。', 'Xin lỗi, anh có thể giải thích lại một lần nữa giúp tôi được không ạ?'),
  ('85292ed2-9958-59e2-9d1b-52ff34967991'::uuid, 'N + に + V (mục đích tặng, làm)', 'Trợ từ に ở đây mang nghĩa làm, để làm (quà tặng, kỷ niệm...).', '田中さんが結婚のお祝いにこの皿をくださいました。', 'Anh Tanaka đã tặng tôi cái đĩa này làm quà mừng cưới.'),
  ('b5698658-fc9c-51aa-9ad3-80aa1540401e'::uuid, 'N の/V辞書形 + ために、~', 'Diễn tả mục đích để, vì; động từ trước ために phải là động từ mang chủ ý, khác với ように có thể đi cả với động từ không chủ ý.', '自分の店を持つために、貯金しています。', 'Tôi đang tiết kiệm tiền để có cửa hàng riêng của mình.'),
  ('ff4acc57-2735-506f-8ef7-0babf3d088ec'::uuid, 'V辞書形の/N + に (mục đích sử dụng)', 'Kết hợp với các từ như つかいます、いい、べんりだ、やくにたつ、じかんがかかる để biểu thị mục đích sử dụng của một vật hay việc.', 'このはさみは花を切るのに使います。', 'Cái kéo này dùng để cắt hoa.'),
  ('2626c1d8-4807-514b-a8be-a42539b85159'::uuid, 'N/V(ます) + に行きます/来ます/帰ります', 'Diễn tả việc đi, đến, về một nơi nào đó nhằm mục đích thực hiện một hành động cụ thể.', '日本へ日本語を勉強しに行きたいです。', 'Tôi muốn đến Nhật Bản để học tiếng Nhật.'),
  ('625eca07-5b5d-56bc-b847-92ef44ef7d4e'::uuid, 'Lượng từ + は (mức tối thiểu)', 'は đứng sau lượng từ để nhấn mạnh đó là mức độ tối thiểu mà người nói ước lượng, cần có.', '日本で結婚式をするのに、200万円はいります。', 'Ở Nhật để tổ chức đám cưới cần ít nhất 2 triệu yên.'),
  ('10c50400-124d-57e0-9b7a-4d207d3ccf71'::uuid, 'Lượng từ + も (nhiều đến mức)', 'も đứng sau con số, lượng từ để nhấn mạnh rằng người nói cảm thấy con số đó là nhiều.', '駅まで行くのに2時間もかかりました。', 'Tôi đã mất đến những 2 tiếng đồng hồ để đi đến ga.'),
  ('2ea0cf56-924d-5cf0-80a9-39d462426a29'::uuid, 'V(ます)/Adjそうです (vẻ ngoài, sắp)', 'Diễn tả sự suy đoán dựa trên quan sát trực quan bằng mắt: với động từ thể ます nghĩa là có vẻ sắp xảy ra, với tính từ (bỏ い/な) nghĩa là trông có vẻ.', 'このケーキはおいしそうです。', 'Cái bánh này trông có vẻ ngon.'),
  ('cd0a4316-44e2-5d4b-ae1c-34d2036ffd68'::uuid, 'Vて + きます (đi làm việc gì rồi về)', 'Diễn tả việc đi đến một nơi để làm gì đó rồi quay trở lại; địa điểm thường dùng で, khi nhấn mạnh sự di chuyển của đồ vật có thể dùng から.', 'ちょっとたばこを買ってきます。', 'Tôi đi mua thuốc lá một chút rồi về.'),
  ('31dda9d8-adaa-5c0b-a904-47ab4793875a'::uuid, 'V(ます)/Adj + すぎます', 'すぎます (động từ nhóm 2) diễn tả một hành động hay trạng thái vượt quá mức, quá giới hạn cho phép.', 'きのうお酒を飲みすぎました。', 'Hôm qua tôi đã uống rượu quá nhiều.'),
  ('276cfd88-6cc2-5ed8-a55d-89c671127ee0'::uuid, 'V(ます) + やすい / にくいです', 'Biểu thị một việc dễ hay khó thực hiện, hoặc một sự vật dễ hay khó thay đổi, xảy ra; chia giống tính từ đuôい.', 'この薬は飲みやすいです。', 'Loại thuốc này dễ uống.'),
  ('80937d60-45e7-58cc-af27-bf7270c38d1d'::uuid, 'Adj/N + します (làm biến đổi)', 'Tính từ い bỏ い thêm く, tính từ な, danh từ bỏ な thêm に, rồi thêm します để diễn tả ai đó chủ động làm biến đổi một đối tượng.', '部屋をきれいにします。', 'Tôi dọn phòng cho sạch sẽ.'),
  ('145b17ac-2171-5629-b5b6-fccf5785aeb8'::uuid, 'N に + します (chọn, quyết định)', 'Biểu thị sự lựa chọn, quyết định có ý chí của người nói đối với một danh từ nào đó.', '晩ご飯はすしにします。', 'Bữa tối tôi chọn ăn sushi.'),
  ('b8b3b66b-fa94-5fda-b4b6-76def8ef61f9'::uuid, 'Adj(く/に) + Động từ', 'Tính từ được biến đổi thành phó từ (く hoặc に) để bổ nghĩa cho động từ đứng sau.', '野菜を細かく切ってください。', 'Hãy thái nhỏ rau.'),
  ('62cd04ee-f6b5-52f8-b9ab-a07016a6d8aa'::uuid, '~ばあいは、~', 'Diễn tả một trường hợp giả định, vế sau là cách xử lý hoặc kết quả trong trường hợp đó; ばあい là danh từ nên cách nối giống bổ nghĩa cho danh từ, thường dùng Vた+ばあい cho tính giả định rõ hơn.', '雨が降った場合は、学校を休みます。', 'Trong trường hợp trời mưa, tôi sẽ nghỉ học.'),
  ('65ab2f9d-6835-556f-b9a2-a0fba7a5e616'::uuid, 'Thể thông thường + のに、~', 'Diễn tả kết quả trái ngược với mong đợi, mang sắc thái bất mãn, ngạc nhiên hoặc trách móc của người nói, sắc thái mạnh hơn が hay ても.', '約束したのに、彼女は来ませんでした。', 'Đã hẹn rồi vậy mà cô ấy đã không đến.'),
  ('62a7bd56-b1f7-5118-a310-26939ceeb550'::uuid, 'Phân biệt のに và が/ても', 'が chỉ đơn thuần nối hai vế có tính đối lập, ても giả định một việc chưa xảy ra; cả hai đều không mang ý nghĩa trái với mong đợi, trong khi のに luôn bao hàm cảm giác bất ngờ, thất vọng của người nói.', 'ダイエットしているのに、太ってしまいました。', 'Tôi đang ăn kiêng vậy mà vẫn béo lên.'),
  ('70e0687e-3251-5945-9e76-4f01ba44052b'::uuid, 'V辞書形/ている/た + ところです', 'ところです nhấn mạnh vị trí của thời điểm hiện tại trong tiến trình một hành động: V辞書形+ところです (sắp làm), Vているところです (đang làm, mạnh hơn ~ています), Vたところです (vừa mới làm xong).', '今から昼ご飯を食べるところです。', 'Bây giờ tôi sắp ăn cơm trưa.'),
  ('6ca7fcc7-3b55-5af6-924e-dbd2133925d2'::uuid, 'Vた + ばかりです', 'Diễn tả hành động vừa mới hoàn thành, kết thúc chưa lâu theo cảm nhận chủ quan của người nói, có thể là vừa xong hoặc đã một thời gian.', 'このカメラは昨日買ったばかりです。', 'Cái máy ảnh này hôm qua tôi vừa mới mua.'),
  ('ed06007f-882c-5450-a6b4-afc778793474'::uuid, '~はずです', 'Biểu thị sự phán đoán chắc chắn của người nói dựa trên một căn cứ cụ thể.', 'ミラーさんは来るはずですよ。昨日電話がありましたから。', 'Chắc chắn anh Miller sẽ đến đấy. Vì hôm qua tôi có nhận được điện thoại của anh ấy.'),
  ('40fa221d-6a1c-5c29-8345-b1692ef09e72'::uuid, 'Thể thông thường + そうです (nghe nói)', 'Dùng để truyền đạt lại thông tin nghe, đọc được từ nguồn khác mà không thêm ý kiến cá nhân, thường dùng kèm ~によると để nêu nguồn tin; khác với ~そうです chỉ vẻ bề ngoài đã học ở bài 43.', '天気予報によると、明日は寒くなるそうです。', 'Theo dự báo thời tiết, nghe nói ngày mai trời sẽ trở lạnh.'),
  ('c0b4d757-e730-5317-8f8b-7712054dc9d6'::uuid, 'Thể thông thường + ようです', 'Biểu thị sự suy đoán mang tính chủ quan của người nói dựa trên thông tin thu thập được qua các giác quan; khác với そうです (nghe nói) là dựa trên nguồn tin gián tiếp.', '咳も出るし、頭が痛い。どうも風邪をひいたようだ。', 'Tôi bị ho lại còn đau đầu nữa. Hình như tôi bị cảm rồi.'),
  ('4c8940ad-eb32-5ab4-bd68-23e7609be5a8'::uuid, 'こえ/におい/おと/あじが します', 'Diễn tả những hiện tượng được cảm nhận qua các giác quan (nghe, ngửi, nếm).', '変な音がします。', 'Tôi nghe thấy có tiếng động lạ.'),
  ('ca9e04fb-2450-57e2-bbcd-52a78bc0aad1'::uuid, 'Vさせます (thể sai khiến)', 'Nhóm 1: đổi âm cuối い→あ rồi thêm せます; nhóm 2: bỏ る thêm させます; nhóm 3: きます→こさせます, します→させます. Diễn tả việc người có địa vị, quyền cao hơn (cha mẹ, cấp trên, giáo viên) bắt buộc hoặc cho phép người khác làm một việc gì đó.', '先生は学生に本を読ませます。', 'Giáo viên bắt học sinh đọc sách.'),
  ('d5541e8d-4690-5626-a668-2152368591ed'::uuid, 'Nを + Vさせます (sai khiến với tự động từ)', 'Khi động từ gốc là tự động từ, không có tân ngữ, thì đối tượng bị sai khiến được đánh dấu bằng trợ từ を.', '母は子供を買い物に行かせました。', 'Mẹ đã cho con đi mua đồ.'),
  ('67e111e1-6f79-5093-be51-29254ad15959'::uuid, 'Nに Nを + Vさせます (sai khiến với tha động từ)', 'Khi động từ gốc là tha động từ, có tân ngữ đi với を, thì đối tượng bị sai khiến được đánh dấu bằng に, còn tân ngữ vẫn giữ を.', '課長は部下にレポートを書かせました。', 'Trưởng phòng đã bắt cấp dưới viết báo cáo.'),
  ('83e3bfc2-2ac6-5a67-bdcf-08355ed9ce7d'::uuid, 'Vさせて + ください', 'Dùng khi người nói xin phép được tự mình làm một việc gì đó, thể hiện mong muốn hoặc thiện chí của người nói.', 'すみませんが、今日休ませてください。', 'Xin lỗi, hôm nay cho tôi nghỉ ạ.'),
  ('241734b9-b050-5f91-9872-f9d23f3a7f11'::uuid, 'Vさせられます (thể bị sai khiến)', 'Là thể bị động của thể sai khiến, diễn tả người nói bị ép buộc làm một việc mà bản thân không muốn làm.', '子供のとき、よく妹の面倒を見させられました。', 'Hồi nhỏ tôi thường bị bắt phải trông em gái.'),
  ('dba87dad-fb6d-513f-aa85-473d44aac9e3'::uuid, 'Kính ngữ - tổng quan', 'Kính ngữ dùng để thể hiện sự tôn trọng với người nghe, người được nhắc đến, được sử dụng khi người nói có địa vị, tuổi tác thấp hơn, khi chưa thân quen, hoặc phân biệt theo quan hệ trong-ngoài (khi nói với người ngoài về người cùng nhóm với mình thì không dùng kính ngữ cho người đó).', '社長はもうお帰りになりました。', 'Giám đốc đã về rồi ạ.'),
  ('be1645b3-1a8a-5f7e-8743-9917ec2dbb4b'::uuid, '3 loại kính ngữ', 'Kính ngữ tiếng Nhật gồm ba loại: そんけいご (tôn kính ngữ, nâng cao người nghe hay người được nói tới), けんじょうご (khiêm nhường ngữ, hạ thấp bản thân), và ていねいご (thể lịch sự, lời nói lịch sự nói chung).', '先生がいらっしゃいました。', 'Thầy giáo đã đến ạ.'),
  ('0d039701-78dc-5a6f-bb27-b47eec3dbe00'::uuid, 'Tôn kính ngữ (尊敬語)', 'Cách chia: nhóm 1 đổi い→あ+れる, nhóm 2 thêm られる, nhóm 3: くる→こられる, する→される; mức cao hơn dùng お+V(ます)+になります. Ngoài ra có các động từ tôn kính đặc biệt (いらっしゃる, めしあがる,...) và cách thêm お/ご trước danh từ, tính từ.', '部長はもうお帰りになりました。', 'Trưởng phòng đã về rồi ạ.'),
  ('e25300c5-b5aa-5887-bf65-bfdd0c516ddd'::uuid, 'Kính ngữ với thể thông thường', 'Kính ngữ có thể kết hợp với thể thông thường ở cuối câu, thường dùng khi nói với người thân thiết về một người cần thể hiện sự kính trọng.', '部長は何時にいらっしゃる?', 'Mấy giờ trưởng phòng sẽ đến vậy?'),
  ('858c6a73-40e3-5ef4-898c-d50f3e8112ef'::uuid, 'Tính nhất quán khi dùng kính ngữ', 'Khi đã dùng kính ngữ trong câu thì nên duy trì nhất quán cho các thành phần liên quan trong câu, không chỉ dùng cho một bộ phận.', '部長の奥様もご一緒にゴルフに行かれます。', 'Phu nhân của trưởng phòng cũng cùng đi chơi golf.'),
  ('f8e657fb-ef0e-5c58-9dcb-891edc2a7ef8'::uuid, 'Vて → Vまして (lịch sự)', 'Trong văn nói lịch sự, thể て của động từ có thể được biến đổi thành まして để giữ tính nhất quán, trang trọng của câu.', 'ゆうべ熱を出しまして、けさもまだ下がらないんです。', 'Tối qua tôi bị sốt, sáng nay vẫn chưa hạ.'),
  ('a295623a-8301-5bb7-8f86-0e1b93475dd2'::uuid, 'Khiêm nhường ngữ お/ご + V(ます) + します', 'Cách hạ mình để thể hiện sự kính trọng khi nói về hành vi của bản thân hướng tới người nghe, người được nhắc tới: động từ nhóm 1, 2 dùng お+V(ます)+します, động từ nhóm 3 gốc Hán dùng ご+Vします; ngoài ra có các động từ khiêm nhường đặc biệt (まいります, いただきます, おります...).', '重そうですね。お持ちしましょうか。', 'Trông nặng quá nhỉ. Để tôi mang giúp anh chị nhé.'),
  ('aac16e81-525c-5b3c-8d42-b7bb275ac760'::uuid, 'Thể lịch sự (丁寧語)', 'Là cách nói lịch sự chung khi giao tiếp với người nghe, ví dụ ございます là thể lịch sự của あります, でございます là thể lịch sự của です, よろしいでしょうか là thể lịch sự của いいですか.', 'お飲み物は何がよろしいでしょうか。', 'Quý khách dùng đồ uống gì ạ?')
) as v(id, title, explanation, example_jp, example_vi)
on conflict (id) do nothing;
-- Seed N4 — Kanji (Minna no Nihongo Kanji Renshuuchou II, Bài 26-50)
-- Nguồn: kiến thức chuẩn giáo trình (jes.edu.vn không liệt kê kanji theo bài),
-- lọc từ tập ứng viên trích xuất từ bảng từ vựng N4 cào thật.
-- Không có mnemonic/stroke_data (SVG) -- ngoài phạm vi yêu cầu.
insert into kanji (id, character, onyomi, kunyomi, meaning_vi, han_viet, stroke_count, level_id)
select v.id, v.character, v.onyomi, v.kunyomi, v.meaning_vi, v.han_viet, v.stroke_count,
       (select id from jlpt_levels where code = 'N4')
